// The "granted nothing" benchmark fixture dependency. See package.json for why this is a
// separate package from `bench-dep` rather than a second entry point on it.
//
// It exists to time the ENFORCE-MODE DENY path — attribute -> evaluate -> throw — for surfaces
// whose allowed form is dominated by real I/O (a real `connect()` does async DNS and socket
// work; a real `spawnSync` forks a process; a real `fetch` opens a connection), so a paired
// allowed-vs-unshimmed delta would measure the OS more than it measures capwall. The deny path
// is also the one an attacker's call actually takes, so it is worth a number of its own.
//
// The duplication with bench-dep's helpers is deliberate and load-bearing: attribution charges
// the NEAREST frame, so a call routed through bench-dep's code would be attributed to
// `bench-dep` and allowed. These frames have to live in this package.
"use strict";
const fs = require("fs");
const net = require("net");
const child_process = require("child_process");
const path = require("path");

const fetchFn = globalThis.fetch;
const DATA = path.join(__dirname, "..", "bench-dep", "data.txt");

/** fs read, denied: no `fs` grant for this package. */
exports.readDenied = () => {
  try {
    return { threw: false, value: fs.readFileSync(DATA, "utf8") };
  } catch (err) {
    return { threw: true, name: err && err.name };
  }
};

/** net connect, denied: the shim throws before any socket opens. */
exports.connectDenied = (host, port) => {
  try {
    const s = net.connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return { threw: false };
  } catch (err) {
    return { threw: true, name: err && err.name };
  }
};

/** spawnSync, denied: the gate throws before any process is created. */
exports.spawnDenied = (cmd, args) => {
  try {
    child_process.spawnSync(cmd, args);
    return { threw: false };
  } catch (err) {
    return { threw: true, name: err && err.name };
  }
};

/**
 * `fetch`, denied — the GLOBAL egress guard (#80). Denial arrives as a REJECTED PROMISE, not a
 * synchronous throw, so the harness has to await it; the guard work (pin the URL argument,
 * parse it into capwall's own `URL`, attribute, evaluate) has all happened by the time the
 * promise exists.
 */
exports.fetchDenied = (url) => fetchFn(url);
exports.hasFetch = typeof fetchFn === "function";
